OH = (IH - 1) * stride - 2 * padding + KH + output_padding
OW = (IW - 1) * stride - 2 * padding + KW + output_padding

m_nn = nn.ConvTranspose3d(IC, OC, KD, stride=stride, padding=padding, output_padding=output_padding).cuda()
x = torch.randn(B, IC, ID, IH, IW).cuda()

